import logging
import random
import time

from py_service_discovery.service_discovery_client import ServiceDiscoveryClient

class ServiceDiscovery(object):
    def __init__(self, service_name, service_port, service_urls):
        self._service_name = service_name
        self._service_port = service_port
        self._service_urls = service_urls
        self._service_discovery_client = ServiceDiscoveryClient(service_name, service_port, service_urls)
        self._logger = logging.getLogger(__name__)

    def get_service_url(self):
        self._logger.debug('Getting service url for %s', self._service_name)
        return self._service_discovery_client.get_service_url()

    def get_service_urls(self):
        self._logger.debug('Getting service urls for %s', self._service_name)
        return self._service_discovery_client.get_service_urls()

    def get_service_url_random(self):
        self._logger.debug('Getting service url for %s', self._service_name)
        return random.choice(self._service_discovery_client.get_service_urls())

    def get_service_url_random_timeout(self, timeout):
        self._logger.debug('Getting service url for %s', self._service_name)
        return self._service_discovery_client.get_service_url_random_timeout(timeout)

    def get_service_url_random_timeout_retry(self, timeout, retry):
        self._logger.debug('Getting service url for %s', self._service_name)
        return self._service_discovery_client.get_service_url_random_timeout_retry(timeout, retry)

    def get_service_url_random_timeout_retry_interval(self, timeout, retry, interval):
        self._logger.debug('Getting service url for %s', self._service_name)
        return self._service_discovery_client.get_service_url_random_timeout_retry_interval(timeout, retry, interval)

